PROGRAM ST_L02_PALLETERING
VAR
    steg     : INT := 0;
    trigDone : R_TRIG;
END_VAR

trigDone(CLK := ST160_RB_DONE);

IF NOT EMG_OK THEN
    ST160_RB_START := FALSE;
    ST160_VAC_ON   := FALSE;
    ST160_SHT_REQ  := FALSE;
    ST160_PLT_DONE := FALSE;
    steg := 0;
ELSE
    CASE steg OF
        0:
            ST160_PLT_DONE := FALSE;
            ST160_SHT_REQ  := FALSE;
            ST160_RB_START := FALSE;
            ST160_VAC_ON   := FALSE;
            ST160_LYR_NO   := 1;
            ST160_LYR_CNT  := 0;
            IF EMG_OK THEN
                steg := 1;
            END_IF;
        1:
            IF NOT ST160_RB_DONE AND ST160_LYR_CNT < 8 THEN
                ST160_RB_START := TRUE;
                ST160_VAC_ON   := TRUE;
                steg := 2;
            END_IF;
        2:
            IF trigDone.Q THEN
                ST160_RB_START := FALSE;
                ST160_VAC_ON   := FALSE;
                ST160_LYR_CNT  := ST160_LYR_CNT + 1;
                IF ST160_LYR_CNT >= 8 THEN
                    IF ST160_LYR_NO < 3 THEN
                        steg := 3;
                    ELSE
                        ST160_PLT_DONE := TRUE;
                        steg := 5;
                    END_IF;
                ELSE
                    steg := 1;
                END_IF;
            END_IF;
        3:
            ST160_SHT_REQ := TRUE;
            IF ST160_SHT_PRS THEN
                steg := 4;
            END_IF;
        4:
            ST160_SHT_REQ := FALSE;
            ST160_LYR_NO  := ST160_LYR_NO + 1;
            ST160_LYR_CNT := 0;
            steg := 1;
        5:
            ST160_PLT_DONE := TRUE;
            ST160_RB_START := FALSE;
            ST160_VAC_ON   := FALSE;
            ST160_SHT_REQ  := FALSE;
    END_CASE;
END_IF;
END_PROGRAM

